import React, { useState } from 'react';

const QuizPage = () => {
  const [formData, setFormData] = useState({
    subject: '',
    examType: '',
    difficulty: '',
    classYear: '',
    topics: [],
    quizMode: '',
    addHints: false,
    timeLimit: '',
    adaptiveDifficulty: false,
    answerExplanation: false,
    questionSource: '',
    examMode: false,
    breakIntoSubtopics: false,
    studentName: '',
    feedback: false,
    language: '',
    mobileMode: false,
    randomizeOrder: false,
    multipleCorrect: false,
    scoreWeighting: false,
    allowRetry: false,
    trackProgress: false,
    personalizedRecommendations: false,
    completionCertificate: false,
  });

  // Handle changes for different inputs
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleMultiChange = (e) => {
    const { value, checked } = e.target;
    if (checked) {
      setFormData((prevData) => ({
        ...prevData,
        topics: [...prevData.topics, value],
      }));
    } else {
      setFormData((prevData) => ({
        ...prevData,
        topics: prevData.topics.filter((topic) => topic !== value),
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle form submission (e.g., send data to backend)
    console.log(formData);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto bg-white shadow-md rounded-lg">
      <h2 className="text-2xl font-bold mb-6">Quiz Configuration</h2>

      <form onSubmit={handleSubmit}>
        {/* Subject Selection */}
        <div className="mb-4">
          <label className="block font-semibold">Subject</label>
          <select
            name="subject"
            value={formData.subject}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Subject</option>
            <option value="Mathematics">Mathematics</option>
            <option value="Physics">Physics</option>
            <option value="Chemistry">Chemistry</option>
            <option value="Biology">Biology</option>
            <option value="Computer Science">Computer Science</option>
            {/* Add more subjects here */}
          </select>
        </div>

        {/* Exam Type */}
        <div className="mb-4">
          <label className="block font-semibold">Exam Type</label>
          <select
            name="examType"
            value={formData.examType}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Exam Type</option>
            <option value="Midterm">Midterm</option>
            <option value="Final Exam">Final Exam</option>
            <option value="Mock Test">Mock Test</option>
            <option value="Certification Exam">Certification Exam</option>
            {/* Add more exam types here */}
          </select>
        </div>

        {/* Difficulty Level */}
        <div className="mb-4">
          <label className="block font-semibold">Difficulty Level</label>
          <div className="flex space-x-4">
            <label>
              <input
                type="radio"
                name="difficulty"
                value="Easy"
                checked={formData.difficulty === "Easy"}
                onChange={handleChange}
              />
              Easy
            </label>
            <label>
              <input
                type="radio"
                name="difficulty"
                value="Medium"
                checked={formData.difficulty === "Medium"}
                onChange={handleChange}
              />
              Medium
            </label>
            <label>
              <input
                type="radio"
                name="difficulty"
                value="Hard"
                checked={formData.difficulty === "Hard"}
                onChange={handleChange}
              />
              Hard
            </label>
          </div>
        </div>

        {/* Class Year */}
        <div className="mb-4">
          <label className="block font-semibold">Class/Exam Year</label>
          <input
            type="text"
            name="classYear"
            value={formData.classYear}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
            placeholder="e.g. 1st Year, 2nd Year"
          />
        </div>

        {/* Topics Selection */}
        <div className="mb-4">
          <label className="block font-semibold">Topics</label>
          <div>
            <label>
              <input
                type="checkbox"
                value="Algebra"
                checked={formData.topics.includes('Algebra')}
                onChange={handleMultiChange}
              />
              Algebra
            </label>
            <label>
              <input
                type="checkbox"
                value="Calculus"
                checked={formData.topics.includes('Calculus')}
                onChange={handleMultiChange}
              />
              Calculus
            </label>
            <label>
              <input
                type="checkbox"
                value="Mechanics"
                checked={formData.topics.includes('Mechanics')}
                onChange={handleMultiChange}
              />
              Mechanics
            </label>
            {/* Add more topics dynamically based on the subject selection */}
          </div>
        </div>

        {/* Additional Quiz Features */}
        <div className="mb-4">
          <label className="block font-semibold">Quiz Features</label>
          <div className="flex space-x-4">
            <label>
              <input
                type="checkbox"
                name="addHints"
                checked={formData.addHints}
                onChange={handleChange}
              />
              Add Hints
            </label>
            <label>
              <input
                type="checkbox"
                name="adaptiveDifficulty"
                checked={formData.adaptiveDifficulty}
                onChange={handleChange}
              />
              Adaptive Difficulty
            </label>
          </div>
        </div>

        {/* Time Limit Options */}
        <div className="mb-4">
          <label className="block font-semibold">Time Limit</label>
          <select
            name="timeLimit"
            value={formData.timeLimit}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Time Limit</option>
            <option value="No Limit">No Limit</option>
            <option value="5 minutes per question">5 minutes per question</option>
            <option value="Total 30 minutes">Total 30 minutes</option>
            {/* More time limits */}
          </select>
        </div>

        {/* Student Name */}
        <div className="mb-4">
          <label className="block font-semibold">Your Name</label>
          <input
            type="text"
            name="studentName"
            value={formData.studentName}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
            placeholder="e.g. John Doe"
          />
        </div>

        {/* Submit Button */}
        <div className="mb-4 text-center">
          <button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded-lg">
            Create Quiz
          </button>
        </div>
      </form>
    </div>
  );
};

export default QuizPage;
